1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.Set;
5	
6	/**
7	 * The single definition of an owner's locality: the canonical region derived from its
8	 * postcode range first (see {@link Postcode}), falling back to a fixed city-to-region table
9	 * when the postcode is absent or in no known range. Owners matching neither resolve to
10	 * {@code "UNKNOWN"}.
11	 *
12	 * <p>Lookup only; a pure function of the postcode and city, so the region is computed on read
13	 * rather than stored.
14	 */
15	public final class Locality {
16	
17	    /** The unknown-region marker returned for any city not in {@link #CITY_REGION}. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    /** City -> canonical region. */
21	    private static final Map<String, String> CITY_REGION =
22	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
23	
24	    /** The canonical regions this application recognises. */
25	    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD");
26	
27	    private Locality() {
28	    }
29	
30	    /** Whether {@code region} is one of the known canonical regions (NSW, VIC or QLD), i.e. any
31	     *  region other than {@link #UNKNOWN}. */
32	    public static boolean isKnown(String region) {
33	        return KNOWN_REGIONS.contains(region);
34	    }
35	
36	    /** The canonical region for {@code city} via the city-to-region table alone, or
37	     *  {@code "UNKNOWN"} when it is not in the table. */
38	    public static String region(String city) {
39	        return CITY_REGION.getOrDefault(city, UNKNOWN);
40	    }
41	
42	    /** The canonical region for an owner: the postcode's region when its range identifies one,
43	     *  otherwise the city's region, or {@code "UNKNOWN"} when neither applies. */
44	    public static String region(String city, String postcode) {
45	        String byPostcode = Postcode.region(postcode);
46	        return byPostcode != null ? byPostcode : region(city);
47	    }
48	}
