1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single definition of the region-to-timezone mapping: the fixed table from an owner's
7	 * canonical region (see {@link Locality}) to its IANA timezone name (NSW-&gt;Australia/Sydney,
8	 * VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Any other region, including
9	 * {@link Locality#UNKNOWN}, has no timezone.
10	 *
11	 * <p>Lookup only; a pure function of the region.
12	 */
13	public final class Timezone {
14	
15	    /** Region -> IANA timezone name. */
16	    private static final Map<String, String> REGION_TIMEZONE =
17	            Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne",
18	                    "QLD", "Australia/Brisbane");
19	
20	    private Timezone() {
21	    }
22	
23	    /** The IANA timezone name for {@code region} via the fixed table, or {@code null} when the
24	     *  region has no mapped timezone. */
25	    public static String of(String region) {
26	        return REGION_TIMEZONE.get(region);
27	    }
28	}
