1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The single definition of an owner's segment, formatted {@code '<TIER>_<AREA>'} and one of
5	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
6	 * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} at membershipLevel 3 or more, otherwise
7	 * {@code STANDARD}; AREA is {@code METRO} for a known region (see {@link Locality#isKnown}),
8	 * otherwise {@code REGIONAL}.
9	 *
10	 * <p>A pure function of the membership level and region, so it is composed on read rather than
11	 * stored.
12	 */
13	public final class OwnerSegment {
14	
15	    private OwnerSegment() {
16	    }
17	
18	    /** The segment for an owner with the given {@code membershipLevel} and canonical
19	     *  {@code region} (see {@link Locality}). A missing membership level is treated as below
20	     *  the premium threshold. */
21	    public static String of(Integer membershipLevel, String region) {
22	        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
23	        String area = Locality.isKnown(region) ? "METRO" : "REGIONAL";
24	        return tier + "_" + area;
25	    }
26	}
