1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of an owner's <em>identity key</em>: the value that decides when
9	 * two owners are the same person. It is the SHA-256 hash of the owner's normalized telephone,
10	 * lower-cased email and the {@link Soundex} code of its last name, so a duplicate is a match
11	 * of the whole hashed key rather than of any single field, and two owners whose last names
12	 * merely sound alike still collide.
13	 *
14	 * <p>Key = {@code sha256Hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))},
15	 * as the full 64-character lower-case hex digest. The telephone and email are already stored
16	 * in canonical form ({@link NormalizeOwnerTelephone} stores the E.164 telephone,
17	 * {@link NormalizeOwnerEmail} the lower-cased email), so the key is built from the owner's
18	 * stored fields; email is lower-cased defensively so the comparison is case-insensitive.
19	 *
20	 * <p>Exposed as a derived, read-only owner field and used by the create endpoint's duplicate
21	 * block (see {@link EnsureUniqueIdentity}): two owners collide only when their whole keys
22	 * match, so owners sharing a last name and postcode but with a different telephone or email
23	 * are admitted as a {@link PossibleDuplicate soft match} rather than rejected.
24	 */
25	public final class IdentityKey {
26	
27	    private IdentityKey() {
28	    }
29	
30	    /** The identity key of an existing owner, derived from its stored fields. */
31	    public static String of(Owner owner) {
32	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
33	    }
34	
35	    /** The identity key for the given normalized telephone, email and last name. */
36	    public static String of(String telephone, String email, String lastName) {
37	        String raw = part(telephone) + "|" + lowerCased(email) + "|" + Soundex.of(lastName);
38	        return Sha256.hexLower(raw);
39	    }
40	
41	    /** A field value, or the empty string when absent. */
42	    private static String part(String value) {
43	        return value == null ? "" : value;
44	    }
45	
46	    /** An email lower-cased, or the empty string when absent. */
47	    private static String lowerCased(String email) {
48	        return email == null ? "" : email.toLowerCase(Locale.ROOT);
49	    }
50	}
