5	/**
6	 * The single definition of an owner's primary identifier: the stable code that identifies
7	 * the owner across the system and in its audit trail. This is the unified
8	 * {@link Owner#getMemberId() memberId}; resolving it here in one place keeps every consumer
9	 * (the {@link OwnerCreatedEvent} included) carrying the same identifier.
10	 */
11	public final class OwnerIdentity {
12	
13	    private OwnerIdentity() {
14	    }
15	
16	    /** The owner's current primary identifier. */
17	    public static String primary(Owner owner) {
18	        return owner.getMemberId();
19	    }
20	}
