1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.OptionalInt;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * The single definition of an owner "household": owners sharing the same last name and
10	 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
11	 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
12	 * shared by the household.
13	 *
14	 * <p>The identifier is derived deterministically from the normalized last name and postcode
15	 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
16	 * postcode} — so every owner with the same last name and postcode resolves to the same value
17	 * regardless of creation order, and no owner-to-owner linking is needed.
18	 *
19	 * @see AssignHousehold stamps each owner with its computed identifier.
20	 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
21	 */
22	final class Household {
23	
24	    /** Length of the household identifier, in hex characters. */
25	    private static final int ID_LENGTH = 12;
26	
27	    private Household() {
28	    }
29	
30	    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
31	     *  and {@code postcode}. */
32	    static String id(String lastName, String postcode) {
33	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
34	        return Sha256.hex(key, ID_LENGTH);
35	    }
36	
37	    /** How many of the given owners belong to the household with {@code householdId}. Owners with a
38	     *  null or non-matching {@code householdId} are not counted; a null {@code householdId} yields 0. */
39	    static long size(String householdId, Iterable<Owner> owners) {
40	        if (householdId == null) {
41	            return 0;
42	        }
43	        long count = 0;
44	        for (Owner owner : owners) {
45	            if (householdId.equals(owner.getHouseholdId())) {
46	                count++;
47	            }
48	        }
49	        return count;
50	    }
51	
52	    /** The highest {@code membershipLevel} among owners in the household with {@code householdId},
53	     *  or empty when it has no such member. Owners with a null or non-matching {@code householdId},
54	     *  or with no level yet, are ignored; a null {@code householdId} yields empty. */
55	    static OptionalInt maxMembershipLevel(String householdId, Iterable<Owner> owners) {
56	        if (householdId == null) {
57	            return OptionalInt.empty();
58	        }
59	        OptionalInt max = OptionalInt.empty();
60	        for (Owner owner : owners) {
61	            Integer level = owner.getMembershipLevel();
62	            if (householdId.equals(owner.getHouseholdId()) && level != null
63	                    && (max.isEmpty() || level > max.getAsInt())) {
64	                max = OptionalInt.of(level);
65	            }
66	        }
67	        return max;
68	    }
69	
70	    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
71	    private static String normalizeName(String value) {
72	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
73	    }
74	}
