1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Create-owner step: stamps the new owner with its {@link Household} identifier, computed
8	 * deterministically from its own last name and postcode. Every owner sharing a last name and
9	 * postcode therefore resolves to the same {@code householdId} without any owner-to-owner
10	 * linking. A household is keyed on the postcode, so an owner without one has no household and
11	 * is left unstamped.
12	 *
13	 * <p>Runs after {@link BuildOwner}, so the household identifier is in place for the later
14	 * household-scoped steps ({@link AssignMembershipLevel}) that key off it. Owner identity no
15	 * longer depends on the household — see {@link IdentityKey}.
16	 */
17	public class AssignHousehold {
18	
19	    public void service(@Val Owner owner) {
20	        String postcode = owner.getPostcode();
21	        if (postcode == null || postcode.isBlank()) {
22	            return;
23	        }
24	        owner.setHouseholdId(Household.id(owner.getLastName(), postcode));
25	    }
26	}
