1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.function.Predicate;
5	
6	/**
7	 * The single definition of an owner's <em>member id</em>: the unified identifier
8	 * {@code <REGION><FY><HASH8><CHK>} that replaces the former customer code and membership
9	 * number. Its segments are:
10	 * <ul>
11	 *   <li>{@code REGION} — the region derived from the owner's postcode (see {@link Locality});</li>
12	 *   <li>{@code FY} — the two-digit {@link FiscalYear fiscal year} of the registration date;</li>
13	 *   <li>{@code HASH8} — the first 8 upper-case hex characters of SHA-256 over the owner's
14	 *       normalized telephone followed by its last name (the same HASH8 the region-and-hash
15	 *       identity uses);</li>
16	 *   <li>{@code CHK} — a single {@link Luhn} check digit over the digits of
17	 *       {@code <REGION><FY><HASH8>}.</li>
18	 * </ul>
19	 *
20	 * <p>The region and fiscal-year segments can be read back from a formatted id (see
21	 * {@link #region} and {@link #fiscalYear}), so the derived region, locality and fiscal-year
22	 * fields all reference the member id rather than recomputing from the raw inputs.
23	 *
24	 * <p>Formatting and parsing only; the region and identity fields are supplied by the caller
25	 * ({@link AssignMemberId} derives the region and reads the stored fields).
26	 */
27	public final class MemberId {
28	
29	    private static final int HASH_LENGTH = 8;
30	
31	    /** Length of the two-digit fiscal-year segment that follows the region. */
32	    private static final int FY_LENGTH = 2;
33	
34	    private MemberId() {
35	    }
36	
37	    /**
38	     * Format a member id {@code <REGION><FY><HASH8><CHK>}, e.g.
39	     * {@code format("NSW", 2026-07-01, "+61412345678", "Smithers")} yields
40	     * {@code "NSW261A2B3C4D<chk>"}: region {@code NSW}, fiscal year {@code 26}, the 8 upper-case
41	     * hex HASH8 of SHA-256 over {@code telephone + lastName}, and the Luhn check digit over the
42	     * digits of {@code <REGION><FY><HASH8>}.
43	     */
44	    public static String format(String region, LocalDate registrationDate, String telephone,
45	            String lastName) {
46	        String base = region + fySegment(registrationDate) + hash8(telephone, lastName);
47	        return base + Luhn.checkDigit(base);
48	    }
49	
50	    /**
51	     * De-duplicate {@code memberId} against ids already in use. If {@code memberId} is free it is
52	     * returned unchanged; otherwise {@code -<n>} is appended with the smallest {@code n >= 2}
53	     * that yields an unused id. The suffix leaves {@link #region(String)} and
54	     * {@link #fiscalYear(String)} unchanged.
55	     *
56	     * @param memberId the freshly formatted id
57	     * @param inUse    tests whether a candidate id is already taken
58	     */
59	    public static String deduplicate(String memberId, Predicate<String> inUse) {
60	        if (!inUse.test(memberId)) {
61	            return memberId;
62	        }
63	        for (int n = 2; ; n++) {
64	            String candidate = memberId + "-" + n;
65	            if (!inUse.test(candidate)) {
66	                return candidate;
67	            }
68	        }
69	    }
70	
71	    /** The region segment of {@code memberId} (the leading letters before the fiscal-year
72	     *  digits), or {@code null} when the id is absent. */
73	    public static String region(String memberId) {
74	        if (memberId == null) {
75	            return null;
76	        }
77	        int i = 0;
78	        while (i < memberId.length() && !Character.isDigit(memberId.charAt(i))) {
79	            i++;
80	        }
81	        return memberId.substring(0, i);
82	    }
83	
84	    /** The fiscal-year label {@code "FY<YY>"} read back from the two digits after the region of
85	     *  {@code memberId}, or {@code null} when the id is absent or malformed. */
86	    public static String fiscalYear(String memberId) {
87	        if (memberId == null) {
88	            return null;
89	        }
90	        int start = region(memberId).length();
91	        if (memberId.length() < start + FY_LENGTH) {
92	            return null;
93	        }
94	        return "FY" + memberId.substring(start, start + FY_LENGTH);
95	    }
96	
97	    /** The two-digit fiscal-year segment for {@code registrationDate}. */
98	    private static String fySegment(LocalDate registrationDate) {
99	        return String.format("%02d", FiscalYear.shortYear(registrationDate));
100	    }
101	
102	    /** The first 8 upper-case hex characters of SHA-256 over {@code telephone + lastName}. */
103	    private static String hash8(String telephone, String lastName) {
104	        return Sha256.hex(telephone + lastName, HASH_LENGTH);
105	    }
106	}
107

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Step of {@code POST /api/owners}: assigns the new owner's {@code memberId}. The id is
12	 * {@code <REGION><FY><HASH8><CHK>} — the region derived from the owner's postcode (see
13	 * {@link Locality}), the two-digit fiscal year of the registration date, a stable hash of the
14	 * owner's normalized telephone and last name, and a Luhn check digit. It runs after the
15	 * telephone has been normalized (so the hash covers the E.164 value) and the registration date
16	 * has been resolved (so the fiscal-year segment is final), and is persisted with the row and
17	 * returned on later reads.
18	 *
19	 * <p>Should the formatted id collide with an existing owner's {@code memberId}, it is
20	 * de-duplicated by appending {@code -<n>} (see {@link MemberId#deduplicate}).
21	 *
22	 * @see MemberId for the {@code <REGION><FY><HASH8><CHK>} format.
23	 */
24	public class AssignMemberId {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String region = Locality.region(owner.getCity(), owner.getPostcode());
28	        String memberId = MemberId.format(region, owner.getRegistrationDate(),
29	                owner.getTelephone(), owner.getLastName());
30	        Set<String> inUse = new HashSet<>();
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (existing.getMemberId() != null) {
33	                inUse.add(existing.getMemberId());
34	            }
35	        }
36	        owner.setMemberId(MemberId.deduplicate(memberId, inUse::contains));
37	    }
38	}
