1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The single definition of the <em>Luhn check digit</em>: the digit (0-9) that, appended to
5	 * a sequence of digits, makes the whole pass the Luhn checksum. Non-digit characters in the
6	 * input are ignored, so it can be computed directly over a formatted value such as a
7	 * {@link MemberId member id}.
8	 *
9	 * <p>Pure function of its input.
10	 */
11	public final class Luhn {
12	
13	    private Luhn() {
14	    }
15	
16	    /** The Luhn check digit (0-9) over the digits contained in {@code value}. */
17	    public static int checkDigit(String value) {
18	        int sum = 0;
19	        boolean doubled = true;
20	        for (int i = value.length() - 1; i >= 0; i--) {
21	            char c = value.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int digit = c - '0';
26	            if (doubled) {
27	                digit *= 2;
28	                if (digit > 9) {
29	                    digit -= 9;
30	                }
31	            }
32	            sum += digit;
33	            doubled = !doubled;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
38

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * The single definition of the American Soundex code of a name: its first letter followed by
5	 * three digits that encode the remaining consonant sounds, so names that sound alike share a
6	 * code. Used by the owner {@link IdentityKey} (which hashes the code, not the raw last name)
7	 * and by the {@link PossibleDuplicate} soft match, so both agree on when two surnames are
8	 * phonetically the same.
9	 *
10	 * <p>Pure function of its input; no state. Letters are the only characters considered; a value
11	 * with no letters yields the all-zero code {@code "0000"}.
12	 */
13	final class Soundex {
14	
15	    /** Length of a Soundex code: an initial letter plus three digits. */
16	    private static final int CODE_LENGTH = 4;
17	
18	    private Soundex() {
19	    }
20	
21	    /** The Soundex code of {@code name}: an upper-case initial letter plus three digits. */
22	    static String of(String name) {
23	        if (name == null) {
24	            return "0000";
25	        }
26	        StringBuilder code = new StringBuilder(CODE_LENGTH);
27	        int previous = 0;
28	        for (int i = 0; i < name.length() && code.length() < CODE_LENGTH; i++) {
29	            char c = Character.toUpperCase(name.charAt(i));
30	            if (c < 'A' || c > 'Z') {
31	                continue; // only letters are encoded
32	            }
33	            if (code.length() == 0) {
34	                code.append(c); // retain the first letter verbatim
35	                previous = digit(c);
36	                continue;
37	            }
38	            if (c == 'H' || c == 'W') {
39	                continue; // spanned by H/W: leave the previous digit in force
40	            }
41	            int digit = digit(c);
42	            if (digit != 0 && digit != previous) {
43	                code.append(digit);
44	            }
45	            previous = digit; // a vowel (digit 0) resets, so a repeat across it is coded twice
46	        }
47	        if (code.length() == 0) {
48	            return "0000"; // no letters at all
49	        }
50	        while (code.length() < CODE_LENGTH) {
51	            code.append('0');
52	        }
53	        return code.toString();
54	    }
55	
56	    /** The Soundex digit of an upper-case letter, or 0 for a letter that is not coded. */
57	    private static int digit(char c) {
58	        switch (c) {
59	            case 'B': case 'F': case 'P': case 'V':
60	                return 1;
61	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
62	                return 2;
63	            case 'D': case 'T':
