1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The single definition of the project's SHA-256 hashing over the UTF-8 bytes of a string.
9	 * The owner {@link MemberId member id} and {@link Household household identifier} take the
10	 * first {@code length} upper-case hex characters; the owner {@link IdentityKey} takes the
11	 * full lower-case digest — all share one implementation rather than each rolling their own.
12	 *
13	 * <p>Pure function of its inputs; no state.
14	 */
15	final class Sha256 {
16	
17	    private Sha256() {
18	    }
19	
20	    /** The first {@code length} upper-case hex characters of SHA-256 over {@code value}. */
21	    static String hex(String value, int length) {
22	        byte[] digest = digest(value);
23	        StringBuilder hex = new StringBuilder(length);
24	        for (int i = 0; hex.length() < length; i++) {
25	            hex.append(String.format("%02X", digest[i]));
26	        }
27	        return hex.substring(0, length);
28	    }
29	
30	    /** The full 64-character lower-case hex SHA-256 of {@code value}. */
31	    static String hexLower(String value) {
32	        byte[] digest = digest(value);
33	        StringBuilder hex = new StringBuilder(digest.length * 2);
34	        for (byte b : digest) {
35	            hex.append(String.format("%02x", b));
36	        }
37	        return hex.toString();
38	    }
39	
40	    private static byte[] digest(String value) {
41	        try {
42	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
43	        }
44	        catch (NoSuchAlgorithmException e) {
45	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
46	        }
47	    }
48	}
