3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	import org.springframework.stereotype.Component;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	import tools.jackson.databind.ObjectMapper;
11	
12	/**
13	 * Emits the immutable {@link OwnerCreatedEvent} for a newly created owner to the dedicated
14	 * {@code AUDIT} logger as a single JSON line. Owns the monotonically increasing sequence
15	 * shared across all creates; being a singleton Spring bean, the counter spans the
16	 * application lifetime rather than a single request.
17	 */
18	@Component
19	public class OwnerCreatedEventPublisher {
20	
21	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
22	
23	    private final AtomicLong sequence = new AtomicLong();
24	
25	    private final ObjectMapper objectMapper;
26	
27	    public OwnerCreatedEventPublisher(ObjectMapper objectMapper) {
28	        this.objectMapper = objectMapper;
29	    }
30	
31	    /** Publish the create event for {@code owner}, assigning it the next sequence number. */
32	    public void publish(Owner owner) {
33	        OwnerCreatedEvent event = OwnerCreatedEvent.of(this.sequence.incrementAndGet(), owner);
34	        AUDIT.info(this.objectMapper.writeValueAsString(event));
35	    }
36	}
