3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Create-owner step: the duplicate block. Two owners are the same person when they share the
10	 * same {@link IdentityKey} (normalized telephone, email and the {@link Soundex} of the last
11	 * name), so a request whose key already belongs to an existing owner is rejected with a 409.
12	 * Duplicate detection is the single identity key: an owner sharing another's last name and
13	 * postcode but with a different telephone has a different key and is admitted here (later
14	 * recorded as a {@link FlagPossibleDuplicate possible duplicate}).
15	 *
16	 * <p>Runs after {@link EnsureEmailNotDisposable} (so the email-domain blocklist is applied
17	 * first) and before {@link FlagPossibleDuplicate} and {@link SaveOwner}.
18	 */
19	public class EnsureUniqueIdentity {
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
22	            throws DuplicateIdentityException {
23	        String identityKey = IdentityKey.of(owner);
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.isDeleted()) {
26	                continue; // a soft-deleted owner no longer occupies its identity
27	            }
28	            if (identityKey.equals(IdentityKey.of(existing))) {
29	                throw new DuplicateIdentityException(identityKey);
30	            }
31	        }
32	    }
33	}
