1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.Collection;
5	import java.util.OptionalInt;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Step of {@code POST /api/owners}: assigns the new owner's {@code membershipPoints} and the
13	 * {@code membershipLevel} derived from them. The scoring rules and the points-to-level
14	 * mapping live in {@link MembershipPoints}; this step gathers the factors and stores both
15	 * values. The derived level is then capped to at most one above the highest level already in
16	 * the owner's {@link Household} (uncapped when the household has no existing member). It runs
17	 * after {@link CountNamesakes} so the namesake count is known,
18	 * {@link AssignHousehold} so the household is stamped, and
19	 * {@link ResolveOwnerRegistrationDate} so the registration date is resolved, and before
20	 * {@link SaveOwner} persists the owner and {@link AuditOwnerCreated} records the level. The
21	 * values are stored with the row and returned unchanged on later reads.
22	 */
23	public class AssignMembershipLevel {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        Collection<Owner> existingOwners = ownerRepository.findAll();
27	        // The new owner is not yet persisted, so it is counted here rather than by the repository.
28	        long householdSize = Household.size(owner.getHouseholdId(), existingOwners) + 1;
29	        long tenureFiscalYears = Tenure.fiscalYears(owner.getRegistrationDate(), LocalDate.now());
30	        int points = MembershipPoints.score(owner.getEmail(), owner.getNamesakeCount(), householdSize, tenureFiscalYears);
31	        owner.setMembershipPoints(points);
32	
33	        // A new owner may sit at most one level above the highest already in its household;
34	        // with no existing household member the level is left uncapped.
35	        int level = MembershipPoints.level(points);
36	        OptionalInt householdMax = Household.maxMembershipLevel(owner.getHouseholdId(), existingOwners);
37	        if (householdMax.isPresent()) {
38	            level = MembershipPoints.capToHousehold(level, householdMax.getAsInt());
39	        }
40	        owner.setMembershipLevel(level);
41	    }
42	}
