1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners}: records whether the new owner is a possible duplicate of
9	 * an existing one — sharing the same postcode and a phonetically equal last name but a
10	 * different {@link IdentityKey} (see {@link PossibleDuplicate}). Such an owner is still
11	 * created; the matching owner's id is stored in {@code possibleDuplicateOf} so a later read
12	 * can flag it.
13	 *
14	 * <p>Runs after {@link EnsureUniqueIdentity} has already rejected exact-identity duplicates, so
15	 * a match reaching here is a distinct owner admitted by its differing identity key. The
16	 * earliest-created (lowest id) matching owner is recorded, and no match leaves the field unset.
17	 */
18	public class FlagPossibleDuplicate {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Integer matchId = null;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (existing.isDeleted()) {
24	                continue; // a soft-deleted owner is not a duplicate to flag against
25	            }
26	            if (PossibleDuplicate.matches(existing, owner)) {
27	                Integer id = existing.getId();
28	                if (id != null && (matchId == null || id < matchId)) {
29	                    matchId = id;
30	                }
31	            }
32	        }
33	        owner.setPossibleDuplicateOf(matchId);
34	    }
35	}
